const lessonSeed = <Map<String, Object?>>[
  {'level':'A1','title':'Artikel: der, die, das','summary':'জার্মান বিশেষ্যের আগে সাধারণত একটি নির্দিষ্ট article থাকে।','rule':'der = পুংলিঙ্গ, die = স্ত্রীলিঙ্গ, das = ক্লীবলিঙ্গ। নতুন noun সবসময় article-সহ শিখবে।','example':'der Mann · die Frau · das Kind'},
